create table if not exists uto.town_profiles ( id uuid primary key default gen_random_uuid(), town_id uuid unique references uto.towns(id) on delete cascade, town_name text, province text, slug text, municipality text, district text, ward_count integer, population_estimate integer, dominant_languages text, economy_summary text, key_industries text, top_employers text, unemployment_context text, schools_note text, tvet_or_college text, clinics_hospitals text, taxi_ranks text, shopping_centres text, markets text, industrial_areas text, tourism_assets text, churches_networks text, ngos_cbos text, facebook_groups text, sports_bodies text, connectivity_mtn text, top_problems text, top_opportunities text, node_fit jsonb, priority_partners text, quick_wins text, six_month_goals text, data_confidence text, sources text, notes text, enrichment_source text, enriched_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now() ); alter table uto.town_profiles enable row level security; create index if not exists idx_town_profiles_slug on uto.town_profiles(slug);